import{_ as a,o as t,c as i,ag as n}from"./chunks/framework.DQQHyi2x.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"Claude Deck","text":"Observe work. Review interventions.","tagline":"A self-hosted workspace for bounded coding-agent attempts on GitHub issues","actions":[{"theme":"brand","text":"Start with work","link":"/guide/quick-start"},{"theme":"alt","text":"View product source","link":"https://github.com/adrirubio/claude-deck/tree/master"}]},"features":[{"title":"Overview and Work","details":"Inspect mixed-team tracking, waiting reasons and PR context with explicit filters.","link":"/features/work"},{"title":"Repositories","details":"Distinguish configured enablement from effective intake, polling and advisory overlaps.","link":"/features/repositories"},{"title":"Teams and recovery","details":"Configure rosters, review launch plans and use authorized remedies within finite policies.","link":"/features/agent-teams"},{"title":"Harnesses and manual sessions","details":"Retain native settings and standalone sessions without enabling backlog dispatch.","link":"/features/harnesses"},{"title":"Agent Mail","details":"Inspect durable context requests and handoffs; agent decisions remain separate from human PR review.","link":"/features/agent-mail"}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),s={name:"index.md"};function r(o,e,d,l,c,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h2 id="daily-observation-and-intervention" tabindex="-1">Daily observation and intervention <a class="header-anchor" href="#daily-observation-and-intervention" aria-label="Permalink to &quot;Daily observation and intervention&quot;">​</a></h2><p>Start at <a href="/docs/features/dashboard.html">Overview</a>, follow <a href="/docs/features/work.html">Work</a>, and inspect <a href="/docs/features/repositories.html">Repositories</a> for paused, blocked or unknown intake. Opening observations does not dispatch, send Mail or launch a session. Protected actions have separate confirmation, authorization and state checks.</p><p>Factory filters are independent of the saved native harness preference and local project. <a href="/docs/features/harnesses.html">Harnesses</a>, <a href="/docs/features/agent-teams.html">Teams</a>, <a href="/docs/features/agent-bridge.html">Live sessions</a> and <a href="/docs/features/agent-mail.html">Agent Mail</a> remain useful for manual and configuration-only work.</p><h2 id="available-scope" tabindex="-1">Available scope <a class="header-anchor" href="#available-scope" aria-label="Permalink to &quot;Available scope&quot;">​</a></h2><p>This reference describes the integrated product source candidate. Earlier packaged releases and separately pinned runtime or pilot environments can retain previous navigation and capabilities; integrating source does not upgrade those environments.</p><p><a href="/docs/features/harnesses.html">Harnesses</a> includes the versioned operations/readiness catalog for all five harnesses, bounded local configuration observations and guarded native pages. See the <a href="/docs/api/providers.html">Providers API</a> for the catalog contract. Native adapters remain provider-specific; catalog support does not create an editor or grant authority.</p><p>Configuration checks do not verify model access. Credential readiness remains unknown, and generic provider cards do not establish a team-slot session binding. Conditional operating support still requires the current identity, workspace and approval authority.</p><p>The integrated source includes guided repository configuration, explicit Leader selection through the team&#39;s <code>leader_slot_id</code>, and the delivery <a href="/docs/guide/factory-audit-and-metrics.html">audit ledger and metrics</a>. The operator accepted M1b; that decision does not supply missing observations. This source does not establish M2 or M3 acceptance. The manual Bridge trial is unperformed; pilot participants, human benefit measurements and timing comparisons are unavailable. Promotion, publication, paid execution and deployment require separate authorization.</p><p>Finished tracking does not establish reviewed delivery.</p>',9)])])}const f=a(s,[["render",r]]);export{h as __pageData,f as default};
